1	/**
2	 * Команды утилиты.
3	 *
4	 * `run` принимает argv массивом и возвращает строку вывода: процесс, stdout и коды выхода
5	 * живут только в main.ts, поэтому команды проверяются обычным вызовом функции, без спавна.
6	 * Ошибка пользователя (нет такой команды, нет такой зоны) — `UsageError`, всё остальное
7	 * пробрасывается как есть: это уже дефект программы, а не ввода.
8	 */
9	
10	import { parseArgs } from './args.ts';
11	import { formatTable } from './format.ts';
12	import { quoteLine } from './lookup.ts';
13	import { RATE_PER_KG, ZONES, isZone } from './tariffs.ts';
14	
15	export const USAGE = [
16	  'qstat — справка по тарифам доставки',
17	  '  qstat list                таблица зон: зона, ₽/кг',
18	  '  qstat quote <zone> <kg>   цена отправления',
19	].join('\n');
20	
21	/** Ошибка ввода пользователя: печатается без стека, код выхода 2. */
22	export class UsageError extends Error {}
23	
24	export function run(argv: readonly string[]): string {
25	  const parsed = parseArgs(argv);
26	
27	  switch (parsed.cmd) {
28	    case '':
29	      return USAGE;
30	    case 'list':
31	      return listCommand();
32	    case 'quote':
33	      return quoteCommand(parsed.args);
34	    default:
35	      throw new UsageError(`неизвестная команда «${parsed.cmd}»\n${USAGE}`);
36	  }
37	}
38	
39	/** Таблица зон: зона и ставка в рублях за килограмм. Ставки — целые рубли (см. tariffs.ts). */
40	function listCommand(): string {
41	  return formatTable(ZONES.map((zone) => [zone, RATE_PER_KG[zone] / 100]));
42	}
43	
44	function quoteCommand(args: readonly string[]): string {
45	  const [zone, kgRaw] = args;
46	  if (zone === undefined || kgRaw === undefined) {
47	    throw new UsageError('quote: нужны зона и вес — qstat quote <zone> <kg>');
48	  }
49	  if (!isZone(zone)) {
50	    throw new UsageError(`quote: неизвестная зона «${zone}», допустимы: ${ZONES.join(', ')}`);
51	  }
52	  return quoteLine(zone, Number(kgRaw));
53	}
54

1	/**
2	 * Разбор аргументов командной строки.
3	 *
4	 * Свой парсер, а не библиотека: зависимостей у пакета нет, а нужны ровно две формы —
5	 * `--key value` и `--flag`. Первый токен без `--` — команда, остальные такие же —
6	 * её позиционные аргументы.
7	 *
8	 * `--key` забирает следующий токен как значение, если тот не начинается с `--`. Отсюда
9	 * правило для вызывающих: флаги ставятся ПОСЛЕ позиционных аргументов (`quote msk 2 --json`),
10	 * иначе `--json msk` прочитается как значение `msk` у ключа `json`.
11	 */
12	
13	export interface ParsedArgs {
14	  /** Команда — первый позиционный токен; пустая строка, если его нет. */
15	  cmd: string;
16	  /** Позиционные аргументы после команды, в порядке появления. */
17	  args: string[];
18	  /** `--key value` → строка, `--flag` → true. */
19	  flags: Record<string, string | true>;
20	}
21	
22	export function parseArgs(argv: readonly string[]): ParsedArgs {
23	  let cmd = '';
24	  const args: string[] = [];
25	  const flags: Record<string, string | true> = {};
26	
27	  for (let i = 0; i < argv.length; i++) {
28	    const token = argv[i]!;
29	    if (!token.startsWith('--')) {
30	      if (cmd === '') cmd = token;
31	      else args.push(token);
32	      continue;
33	    }
34	    const key = token.slice(2);
35	    if (key === '') throw new Error('пустое имя флага: «--» без имени');
36	    const next = argv[i + 1];
37	    if (next !== undefined && !next.startsWith('--')) {
38	      flags[key] = next;
39	      i++;
40	    } else {
41	      flags[key] = true;
42	    }
43	  }
44	
45	  return { cmd, args, flags };
46	}
47

