10	 * иначе `--json msk` прочитается как значение `msk` у ключа `json`.
11	 */
12	
13	export interface ParsedArgs {
14	  /** Команда — первый позиционный токен; пустая строка, если его нет. */
15	  cmd: string;
16	  /** Позиционные аргументы после команды, в порядке появления. */
17	  args: string[];
18	  /** `--key value` → строка, `--flag` → true. */
19	  flags: Record<string, string | true>;
20	}
21	
22	export function parseArgs(argv: readonly string[]): ParsedArgs {
23	  let cmd = '';
24	  const args: string[] = [];
25	  const flags: Record<string, string | true> = {};
26	
27	  for (let i = 0; i < argv.length; i++) {
28	    const token = argv[i]!;
29	    if (!token.startsWith('--')) {
30	      if (cmd === '') cmd = token;
31	      else args.push(token);
32	      continue;
33	    }
34	    const key = token.slice(2);
35	    if (key === '') throw new Error('пустое имя флага: «--» без имени');
36	    const next = argv[i + 1];
37	    if (next !== undefined && !next.startsWith('--')) {
38	      flags[key] = next;
39	      i++;
40	    } else {
41	      flags[key] = true;
42	    }
43	  }
44	
45	  return { cmd, args, flags };
46	}
47

1	/**
2	 * Вывод для человека: таблицы и строка цены.
3	 *
4	 * Стандарт вывода денег в проекте один: целые рубли с ПРОБЕЛОМ между разрядами — `1 234 ₽`.
5	 * Копейки печатаются только когда они есть (`1 234,50 ₽`): прейскурант в рублях, и хвост
6	 * `,00` на каждой строке только мешал бы читать.
7	 */
8	
9	import type { Kopeck } from './tariffs.ts';
10	
11	/** Ячейка таблицы: число печатается с группировкой разрядов, строка — как есть. */
12	export type Cell = string | number;
13	
14	// TODO: formatTable дублирует логику formatQuote — отрефакторить
15	/**
16	 * Таблица: колонки выровнены по ширине самой длинной ячейки, разделитель — два пробела,
17	 * хвостовые пробелы строки срезаны. Заголовка нет: команды печатают только данные, чтобы
18	 * вывод можно было передать дальше по конвейеру без `tail -n +2`.
19	 */
20	export function formatTable(rows: readonly (readonly Cell[])[]): string {
21	  const text = rows.map((row) =>
22	    row.map((cell) => (typeof cell === 'number' ? String(cell).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') : cell)),
23	  );
24	
25	  const widths: number[] = [];
26	  for (const row of text) {
27	    row.forEach((cell, i) => {
28	      widths[i] = Math.max(widths[i] ?? 0, cell.length);
29	    });
30	  }
31	
32	  return text
33	    .map((row) =>
34	      row
35	        .map((cell, i) => cell.padEnd(widths[i] ?? 0))
36	        .join('  ')
37	        .trimEnd(),
38	    )
39	    .join('\n');
40	}
41	
42	/** `msk, 2 кг: 458 ₽` — строка цены отправления по стандарту вывода денег. */
43	export function formatQuote(zone: string, kg: number, price: Kopeck): string {
44	  const whole = Math.floor(price / 100);
45	  const cents = price % 100;
46	  const grouped = String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
47	  const tail = cents === 0 ? '' : `,${String(cents).padStart(2, '0')}`;
48	  return `${zone}, ${kg} кг: ${grouped}${tail} ₽`;
49	}
50

1	/**
2	 * Точка входа процесса: `node src/main.ts <команда> …`.
3	 *
4	 * Единственное место, которое знает про process.argv, stdout и код выхода. Всё остальное —
5	 * функции над массивом строк, и тестируется без процесса.
6	 */
7	
8	import { resolve } from 'node:path';
9	import { pathToFileURL } from 'node:url';
10	
11	import { UsageError, run } from './commands.ts';
12	
13	/** Возвращает код выхода, а не зовёт process.exit: так main проверяется как функция. */
14	export function main(argv: readonly string[]): number {
15	  try {
16	    console.log(run(argv));
17	    return 0;
18	  } catch (e) {
19	    if (e instanceof UsageError) {
20	      console.error(e.message);
21	      return 2;
22	    }
23	    throw e;
24	  }
25	}
26	
27	// Исполняется только когда этот файл и есть точка входа. build-check импортирует все модули
28	// src подряд, и без проверки импорт main.ts запускал бы CLI с argv сборки.
29	const entry = process.argv[1];
30	if (entry !== undefined && pathToFileURL(resolve(entry)).href === import.meta.url) {
31	  process.exitCode = main(process.argv.slice(2));
32	}
