1	/**
2	 * Команды утилиты.
3	 *
4	 * `run` принимает argv массивом и возвращает строку вывода: процесс, stdout и коды выхода
5	 * живут только в main.ts, поэтому команды проверяются обычным вызовом функции, без спавна.
6	 * Ошибка пользователя (нет такой команды, нет такой зоны) — `UsageError`, всё остальное
7	 * пробрасывается как есть: это уже дефект программы, а не ввода.
8	 */
9	
10	import { parseArgs } from './args.ts';
11	import { formatTable } from './format.ts';
12	import { quoteLine } from './lookup.ts';
13	import { RATE_PER_KG, ZONES, isZone } from './tariffs.ts';
14	
15	export const USAGE = [
16	  'qstat — справка по тарифам доставки',
17	  '  qstat list                таблица зон: зона, ₽/кг',
18	  '  qstat quote <zone> <kg>   цена отправления',
19	].join('\n');
20	
21	/** Ошибка ввода пользователя: печатается без стека, код выхода 2. */
22	export class UsageError extends Error {}
23	
24	export function run(argv: readonly string[]): string {
25	  const parsed = parseArgs(argv);
26	
27	  switch (parsed.cmd) {
28	    case '':
29	      return USAGE;
30	    case 'list':
31	      return listCommand(parsed.flags);
32	    case 'quote':
33	      return quoteCommand(parsed.args);
34	    default:
35	      throw new UsageError(`неизвестная команда «${parsed.cmd}»\n${USAGE}`);
36	  }
37	}
38	
39	/**
40	 * Таблица зон: зона и ставка в рублях за килограмм. Ставки — целые рубли (см. tariffs.ts).
41	 *
42	 * С флагом `--zone <name>` печатается только строка названной зоны; зоны, которой нет в
43	 * тарифах, — не ошибка, а пустой результат: строка «ничего не найдено», код выхода обычный
44	 * (поддержка вводит имена руками, падение с трассой на опечатке ей не помощник).
45	 */
46	function listCommand(flags: Record<string, string | true>): string {
47	  const zoneFlag = flags['zone'];
48	  const rows = ZONES.filter((zone) => (typeof zoneFlag === 'string' ? zone === zoneFlag : true));
49	  if (rows.length === 0) {
50	    return 'ничего не найдено';
51	  }
52	  return formatTable(rows.map((zone) => [zone, RATE_PER_KG[zone] / 100]));
53	}
54	
55	function quoteCommand(args: readonly string[]): string {
56	  const [zone, kgRaw] = args;
57	  if (zone === undefined || kgRaw === undefined) {
58	    throw new UsageError('quote: нужны зона и вес — qstat quote <zone> <kg>');
59	  }
60	  if (!isZone(zone)) {
61	    throw new UsageError(`quote: неизвестная зона «${zone}», допустимы: ${ZONES.join(', ')}`);
62	  }
63	  return quoteLine(zone, Number(kgRaw));
64	}
